+		// command flow surface it in its own terms.
+		return probeErr
+	}
+	if !interactive.CanPromptInteractively() {
+		return errors.New(msg)
+	}
+	loggedIn, err := interactiveReauthLogin(cmd, loginServer, msg)
+	if err != nil {
+		return err
+	}
+	if !loggedIn {
+		return NewSilentError(errors.New(msg))
+	}
